def f(g):
    h=len(g); w=len(g[0])
    out=[row[:] for row in g]
    cells=[(i,j) for i in range(h) for j in range(w) if g[i][j] not in (0,5)]
    rs=[i for i,j in cells]; cs=[j for i,j in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    pat=[[g[r0+di][c0+dj] for dj in range(c1-c0+1)] for di in range(r1-r0+1)]
    ph,pw=r1-r0+1,c1-c0+1
    # find vertical 5-line adjacent to pattern (left or right)
    vline=None
    for j in range(w):
        n=sum(1 for i in range(h) if g[i][j]==5)
        if n>=2 and (j<c0 or j==c1+1):
            vline=j; break
    if vline is not None:
        top=[i for i in range(h) if g[i][vline]==5]
        t0,t1=min(top),max(top)
        for i in range(t0,t1+1):
            for jj in range(c0,c1+1):
                if g[i][jj]==0:
                    out[i][jj]=pat[(t1-i)%ph][jj-c0]
    return out
